export const PRESETS: readonly PerformancePreset[] = [
    SqookyDefault,
    SqookyTesting,
    BootMaxFps,
    KaizuMinSpec,
    OptilockFps,
    OptilockMax,
];

export const DEFAULT_PRESET_ID = 'sqooky-default';

export function getPreset(id: string | null | undefined): PerformancePreset {
    return PRESETS.find((p) => p.id === id) ?? PRESETS.find((p) => p.id === DEFAULT_PRESET_ID)!;
}
